def _dumps_tree(model):
    """Serialize a fitted DecisionTreeClassifier.

    ``max_depth`` is emitted as a JSON integer or the string ``"none"``
    when it is None; ``n_features_in`` is a positive JSON integer. Each
    node is an object with the keys ``label``, ``feature``, ``threshold``,
    ``left``, ``right`` in that order: leaves carry ``feature`` -1,
    ``threshold`` 0.0000000000 and empty ``left``/``right`` arrays, while
    internal nodes carry a feature index in ``[0, n_features_in)``, a
    10-decimal threshold and child node objects. Construction parameters
    and fitted state are re-validated; anything malformed raises
    ValueError.
    """
    root = model._root
    if root is None:
        raise ValueError(
            "DecisionTreeClassifier must be fitted before dumps is called"
        )
    max_depth = model.max_depth
    # Re-validate the construction parameters exactly as __init__ does.
    if max_depth is not None and (
        type(max_depth) is not int or max_depth < 1
    ):
        raise ValueError(
            "DecisionTreeClassifier has invalid construction parameters"
        )
    n_features = model._n_features
    if type(n_features) is not int or n_features <= 0:
        raise ValueError(
            "DecisionTreeClassifier feature count must be a positive integer"
        )
    if max_depth is None:
        max_depth_text = '"none"'
    else:
        max_depth_text = str(max_depth)
    return (
        '{"class":"DecisionTreeClassifier","max_depth":'
        + max_depth_text
        + ',"n_features_in":'
        + str(n_features)
        + ',"tree":'
        + _encode_tree_node(root, n_features)
        + "}"
    )


def _encode_tree_node(node, n_features):
    if not isinstance(node, _DecisionTreeNode):
        raise ValueError("tree state must contain only tree nodes")
    label = node.label
    if type(label) is not int:
        raise ValueError("tree node labels must be integers")
    label_text = str(label)
    feature = node.feature
    if feature is None:
        if (
            node.threshold is not None
            or node.left is not None
            or node.right is not None
        ):
            raise ValueError("leaf nodes must not carry split state")
        return (
            '{"label":'
            + label_text
            + ',"feature":-1,"threshold":0.0000000000,"left":[],"right":[]}'
        )
    if type(feature) is not int or not 0 <= feature < n_features:
        raise ValueError("internal node feature must be in [0, n_features_in)")
    return (
        '{"label":'
        + label_text
        + ',"feature":'
        + str(feature)
        + ',"threshold":'
        + _quantize_fixed(node.threshold)
        + ',"left":'
        + _encode_tree_node(node.left, n_features)
        + ',"right":'
        + _encode_tree_node(node.right, n_features)
        + "}"
    )


